# Phase 3H / Batch D: the daily-lag layer (XYD, DAY, MAXT). Synthetic data only; no study data and no frozen file is read here.
if (!exists("expect_match", mode = "function")) expect_match <- function(x, pattern) expect_true(isTRUE(all(grepl(pattern, x))))
if (!exists("expect_gt", mode = "function")) expect_gt <- function(a, b) expect_true(a > b)
if (!exists("expect_lt", mode = "function")) expect_lt <- function(a, b) expect_true(a < b)
CFG <- siw_load_config(); PD <- siw_daily_protocol(); hsh <- function(f) siw_file_hash(file.path(ROOT, f))$value
raw0 <- siw_make_synthetic(n = 55L, seed = 21L, config = CFG); DAT <- siw_attach_cumulative(siw_prepare_data(raw0, CFG), CFG)$data

test_that("the protocol is declared before the run: hashed references, counts, traced MAXT family / seed rule / sampling unit / p formula, no invented seed", {
  if (siw_skip_source_only("test-25-daily-layer: the protocol is declared before the run: hashed references, counts, tr")) return(invisible(NULL))
  expect_match(PD$status_of_this_document, "DECLARED BEFORE THE MANUAL RUN"); expect_match(PD$status_of_this_document, "no seed is invented"); expect_equal(length(PD$reference_files), 3L)
  expect_equal(vapply(PD$reference_files, function(z) z$expected_records, 0L), c(1416L, 1416L, 240L)); expect_equal(vapply(PD$comparisons, function(z) z$expected_compared_cells, 0L), c(27848L, 57112L, 480L))
  expect_private(PD$reference_files[[1]]$sha256, "daily_layer_reference_1"); expect_private(PD$reference_files[[2]]$sha256, "daily_layer_reference_2"); expect_private(PD$reference_files[[3]]$sha256, "daily_layer_reference_3")
  M <- PD$specification_trace$MAXT; expect_match(M$family_structure, "3 x 80 = 240"); expect_match(M$family_structure, "NOT part of MAXT"); expect_match(M$permutation, "OUTCOME vector is permuted"); expect_match(M$permutation, "unit: participant"); expect_match(M$seed_and_rng, "20261729, 20262729, 20263729"); expect_match(M$adjusted_p, "1 \\+ #"); expect_match(M$adjusted_p, "1/10,001"); expect_match(M$degenerate_cases, "anti-conservative")
  expect_equal(PD$parameters$maxt_replicates, 10000); expect_equal(PD$parameters$maxt_seed_step, 1000); expect_equal(CFG$seed + c(1L, 2L, 3L) * PD$parameters$maxt_seed_step, c(20261729, 20262729, 20263729)); expect_equal(CFG$glm$cumulative_epsilon, PD$parameters$glm_epsilon); expect_equal(PD$parameters$lag_end, 59)
  expect_equal(PD$tolerance$MAXT$class, "exact"); expect_equal(PD$tolerance$XYD_DAY$within_tolerance$abs, CFG$tolerances$cumulative_abs); expect_match(PD$verification$MAXT_assumptions, "never PASS"); expect_match(PD$statuses$MAXT_ASSUMPTIONS_STATUS, "REVIEW")
  expect_identical(hsh("config/daily_layer_validation_protocol.json"), PD$protocol_hash); expect_identical(hsh("inst/extdata/daily_layer_validation_protocol.json"), PD$protocol_hash); expect_match(PD$status_of_this_document, "separate from the nine final|Separate from the nine final")
  expect_identical(hsh("R/ordinal.R"), "010882F8DFD0756A8577429F8A3E5423F45220F2D39AA0A4067CD2ED73704441"); expect_private(hsh("config/cold_burden_validation_protocol.json"), "cold_burden_validation_protocol"); expect_private(hsh("config/archived_dlm_validation_protocol.json"), "archived_dlm_validation_protocol")
})

test_that("correlation set: hand-calculated example, independent Kendall (ties), boundary and missing-data cases", {
  x <- c(1, 2, 3, 4, 5); y <- c(2, 1, 4, 3, 5); r <- siw_correlation_set_full(x, y); expect_equal(unname(r[["pearson_r"]]), 0.8); expect_equal(unname(r[["spearman_rho"]]), 0.8); expect_equal(unname(r[["kendall_tau"]]), 0.6); expect_equal(unname(r[["n"]]), 5)
  k <- siw_kendall_independent(x, y); expect_equal(unname(k[["tau"]]), 0.6); expect_equal(unname(k[["p"]]), unname(r[["kendall_p"]]), tolerance = 1e-12)
  set.seed(3); for (i in 1:12) { a <- sample(1:5, 20, TRUE); b <- sample(1:4, 20, TRUE); if (length(unique(a)) > 1 && length(unique(b)) > 1) { ref <- suppressWarnings(stats::cor.test(a, b, method = "kendall", exact = FALSE)); kk <- siw_kendall_independent(a, b); expect_equal(unname(kk[["tau"]]), unname(ref$estimate), tolerance = 1e-12); expect_equal(unname(kk[["p"]]), ref$p.value, tolerance = 1e-10) } }
  expect_true(is.na(siw_correlation_set_full(c(1, 2, 3), c(1, 3, 2))[["pearson_r"]])); expect_true(is.na(siw_correlation_set_full(rep(1, 6), 1:6)[["pearson_r"]])); expect_equal(unname(siw_correlation_set_full(c(1, NA, 3, 4, 5, 6), c(2, 5, NA, 1, 9, 3))[["n"]]), 4)
  expect_equal(unname(siw_correlation_set_full(c(1, 2, 3, 4, Inf), 1:5)[["n"]]), 4); yb <- c(0, 0, 1, 1, 1, 0); xb <- c(1, 2, 5, 6, 4, 3); expect_equal(unname(siw_correlation_set_full(xb, yb)[["pearson_r"]]), stats::cor(xb, yb))                      # point-biserial = Pearson on the 0/1 code
})

S_lags <- c(1L, 35L, 59L); XD <- siw_xy_daily_grid(DAT, CFG, PD, lags = S_lags); DY <- siw_single_day_grid(DAT, CFG, PD, lags = S_lags)

test_that("XYD: declared structure (outcome, metric, lag order; keys; q families), independent recomputation of every row, missing rainfall preserved", {
  expect_equal(nrow(XD), 3L * 8L * 3L); expect_equal(nrow(unique(XD[, c("outcome", "metric", "window_or_lag")])), nrow(XD)); expect_equal(XD$outcome[1:9], rep("UCLA_Lonliness_SCORE", 9)); expect_equal(XD$window_or_lag[1:3], S_lags); expect_equal(unique(XD$exposure_type), "daily_lag"); expect_equal(XD$exposure_field[1], "UTCI_L01")
  v <- siw_xy_daily_verify(DAT, CFG, XD); expect_true(all(v$status == "PASS")); expect_true(all(v$max_rel_diff <= 1e-6)); expect_equal(nrow(v), 11L)
  for (nm in c("pearson", "spearman", "model")) { p <- XD[[paste0(nm, "_p")]]; expect_equal(XD[[paste0("q_", nm, "_global")]], stats::p.adjust(p, "BH"), tolerance = 1e-12); for (o in unique(XD$outcome)) { i <- XD$outcome == o; expect_equal(XD[[paste0("q_", nm, "_outcome")]][i], stats::p.adjust(p[i], "BH"), tolerance = 1e-12) } }
  expect_false("q_pearson_outcome_metric" %in% names(XD)); expect_true(all(is.na(XD$nagelkerke_r_squared[XD$outcome_family == "gaussian"]))); expect_true(all(is.finite(XD$nagelkerke_r_squared[XD$outcome_family == "binomial"])))
  miss <- which(vapply(1:59, function(l) anyNA(DAT[[paste0("IMS_IDW_RAIN_TOTAL_L", sprintf("%02d", l))]]), NA)); expect_gt(length(miss), 0L)
  xr <- siw_xy_daily_grid(DAT, CFG, PD, lags = miss[1L]); rr <- xr[xr$metric == "IMS_rainfall_total", ]; expect_true(all(rr$n == nrow(DAT) - 1L)); expect_true(all(xr$n[xr$metric != "IMS_rainfall_total"] == nrow(DAT)))
  m <- XD[XD$outcome == "Isolation_cont" & XD$metric == "UTCI" & XD$window_or_lag == 35L, ]; ft <- stats::lm(DAT$Isolation_cont ~ DAT$UTCI_L35); expect_equal(m$coefficient, unname(stats::coef(ft)[2]), tolerance = 1e-10); expect_equal(m$r_squared, summary(ft)$r.squared, tolerance = 1e-10)
  bad <- XD; bad$kendall_p[2] <- bad$kendall_p[2] * 1.5; expect_true(any(siw_xy_daily_verify(DAT, CFG, bad)$status == "FAIL"))
})

test_that("DAY: declared structure, M2_L complete cases, engine equality, identities, q59 / q472 / q_global, independent refit", {
  expect_equal(nrow(DY), 72L); expect_equal(unique(DY$model_tier), "M2_L"); expect_equal(unique(DY$transformation), "raw_daily"); expect_equal(unique(DY$primary_role), "SUPPLEMENTARY_SINGLE_DAY_DIAGNOSTIC"); expect_equal(DY$model_id[1], "SINGLE_DAY__UCLA_Lonliness_SCORE__UTCI__L01__M2_L"); expect_equal(unique(DY$parameter_count[DY$status == "COMPLETED"]), 8L)
  expect_equal(DY$exposure_unit[DY$metric == "UTCI"][1], "degC"); expect_equal(nrow(unique(DY[, c("outcome", "metric", "window_or_lag", "model_tier")])), 72L)
  ok <- is.finite(DY$nominal_p); expect_equal(DY$q_global[ok], stats::p.adjust(DY$nominal_p[ok], "BH"), tolerance = 1e-12); for (o in unique(DY$outcome)) { i <- which(ok & DY$outcome == o); expect_equal(DY$q472[i], stats::p.adjust(DY$nominal_p[i], "BH"), tolerance = 1e-12); for (m in unique(DY$metric)) { j <- which(ok & DY$outcome == o & DY$metric == m); expect_equal(DY$q59[j], stats::p.adjust(DY$nominal_p[j], "BH"), tolerance = 1e-12) } }
  Xc <- siw_tier_matrix(DAT, CFG$tiers$M2_L); i <- which(DY$outcome == "UCLA_Lonliness_SCORE" & DY$metric == "MRT" & DY$window_or_lag == 35L); X <- cbind(Xc[, 1L, drop = FALSE], exposure = DAT$MRT_L35, Xc[, -1L, drop = FALSE]); st <- siw_fit_gaussian(X, DAT$UCLA_Lonliness_SCORE, 2L); expect_equal(DY$coefficient[i], st$coefficient, tolerance = 1e-12)
  id <- .siw_dl_identities(DY); expect_true(all(id$status == "PASS")); expect_true(any(DY$n == 54L)); rf <- do.call(rbind, lapply(seq(1L, nrow(DY), by = 8L), function(k) { r <- DY[k, ]; ref <- .siw_cold_refit_reference(DAT, CFG, r$outcome, r$outcome_family, as.numeric(DAT[[r$exposure]]), CFG$tiers$M2_L); data.frame(f = names(ref), ok = vapply(names(ref), function(f) abs(r[[f]] - ref[[f]]) <= 1e-7 + 1e-6 * abs(ref[[f]]), NA)) })); expect_true(all(rf$ok))
  expect_true(all(c("condition_number", "maximum_vif", "maximum_leverage", "influential_case_count") %in% names(DY))); expect_false("marginal_probability_difference_per_sd" %in% names(DY)); r2 <- DY; r2$standardised_effect[which(r2$status == "COMPLETED")[3]] <- 9; expect_true(any(.siw_dl_identities(r2)$status == "FAIL"))
})

# ---- MAXT ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
perms <- function(v) { if (length(v) <= 1L) return(list(v)); out <- list(); for (i in seq_along(v)) for (p in perms(v[-i])) out[[length(out) + 1L]] <- c(v[i], p); out }
enum_max <- function(xmat, y) { P <- perms(seq_along(y)); vapply(P, function(ix) { yp <- y[ix]; vals <- abs(vapply(seq_len(ncol(xmat)), function(j) suppressWarnings(stats::cor(xmat[, j], yp, use = "pairwise.complete.obs")), 0)); suppressWarnings(max(vals, na.rm = TRUE)) }, 0) }

test_that("MAXT on small enumerated examples: the maximum statistic equals the full enumeration of all permutations, the exact p value is reproduced within Monte Carlo error, ties and the (1 + count)/(1 + B) rule are hand-verified", {
  set.seed(8); xm <- cbind(a = c(1.2, 3.4, 2.2, 5.1, 4.4, 0.3), b = c(2, 2, 3, 1, 5, 4), c = c(0.1, 0.9, 0.4, 0.7, 0.2, 0.8)); y <- c(3, 1, 4, 1.5, 5, 9)
  Pm <- do.call(rbind, lapply(perms(seq_along(y)), function(ix) y[ix])); expect_equal(nrow(Pm), 720L); mx <- .siw_maxt_max(.siw_maxt_prepare(xm), Pm); expect_equal(mx, enum_max(xm, y), tolerance = 1e-12)
  obs <- abs(vapply(1:3, function(j) stats::cor(xm[, j], y), 0)); exact_p <- vapply(obs, function(o) mean(enum_max(xm, y) >= o - 1e-12), 0); r <- siw_maxt_outcome(xm, y, 20000L, 11L, colnames(xm), "o"); se <- sqrt(exact_p * (1 - exact_p) / 20000L)
  expect_true(all(abs(r$table$p_outcome_maxT - exact_p) <= 4 * se + 1e-3)); expect_equal(r$replicates_requested, 20000L); expect_equal(r$replicates_successful, 20000L)
  mm <- c(0.1, 0.5, 0.5, 0.9); expect_equal((1 + sum(mm >= 0.5)) / (1 + length(mm)), 0.8); expect_equal((1 + sum(mm >= 0.9)) / (1 + length(mm)), 0.4); expect_equal((1 + sum(mm >= 1)) / (1 + length(mm)), 0.2)             # ties count; the observed arrangement is one permutation; minimum 1/(1 + B)
  xb <- cbind(u = c(1, 0, 1, 0, 1, 0), v = c(1, 1, 0, 0, 1, 0)); yb <- c(1, 0, 1, 0, 1, 0); Pb <- do.call(rbind, lapply(perms(1:6), function(ix) yb[ix])); expect_equal(.siw_maxt_max(.siw_maxt_prepare(xb), Pb), enum_max(xb, yb), tolerance = 1e-12)       # binary outcome with many tied statistics
  xn <- xm; xn[2, "b"] <- NA; Pn <- do.call(rbind, lapply(perms(seq_along(y)), function(ix) y[ix])); expect_equal(.siw_maxt_max(.siw_maxt_prepare(xn), Pn), enum_max(xn, y), tolerance = 1e-12)                                  # pairwise-complete column (two NA patterns)
})

test_that("MAXT: the optimised engine reproduces the original sampling sequence and statistics exactly; RNG state is restored; seeds follow the traced rule; near ties are recomputed by the original route", {
  set.seed(5); xm <- matrix(round(stats::rnorm(40 * 12, 10, 3)), 40, 12, dimnames = list(NULL, paste0("f", 1:12))); xm[3, 4] <- NA; xm[7, 9] <- NA; xm[, 12] <- 5; y <- stats::rnorm(40)
  o <- siw_maxt_outcome(xm, y, 400L, 99L, colnames(xm), "o"); l <- siw_maxt_legacy(xm, y, 400L, 99L); expect_equal(o$max_stats, l$max_stats, tolerance = 1e-12); expect_identical(o$table$p_outcome_maxT, l$p); expect_identical(o$table$observed_abs_correlation, l$observed); expect_true(is.na(l$observed[12]))
  set.seed(77); u1 <- stats::runif(1); set.seed(77); invisible(siw_maxt_outcome(xm, y, 50L, 3L, colnames(xm), "o")); expect_equal(stats::runif(1), u1)                         # the caller's RNG state is restored
  s1 <- siw_with_seed(99L, sample(y)); set.seed(99L, kind = "Mersenne-Twister", normal.kind = "Inversion", sample.kind = "Rejection"); expect_equal(s1, sample(y)); Y <- siw_with_seed(99L, { M <- matrix(0, 2, length(y)); for (b in 1:2) M[b, ] <- sample(y); M }); set.seed(99L); a1 <- sample(y); a2 <- sample(y); expect_equal(Y[1, ], a1); expect_equal(Y[2, ], a2)
  yb <- rep(c(0, 1), each = 10); xb <- cbind(g1 = rep(c(0, 1), each = 10), g2 = rep(c(1, 0), 10), g3 = c(1:10, 1:10)); ob <- siw_maxt_outcome(xb, yb, 300L, 5L, colnames(xb), "o"); lb <- siw_maxt_legacy(xb, yb, 300L, 5L); expect_gt(ob$near_tie_recomputed, 0L); expect_identical(ob$table$p_outcome_maxT, lb$p); expect_equal(ob$max_stats, lb$max_stats, tolerance = 1e-12)
  g <- siw_xy_maxt_grid(DAT, CFG, PD, replicates = 200L); expect_equal(g$diagnostics$seed, c(20261729, 20262729, 20263729)); expect_equal(nrow(g$table), 240L); expect_equal(as.vector(table(g$table$outcome)), c(80L, 80L, 80L)); expect_equal(nrow(unique(g$table[, c("outcome", "exposure_field")])), 240L); expect_equal(g$table$exposure_field[1:3], c("UTCI_AVG_1D", "UTCI_AVG_3D", "UTCI_AVG_7D"))
  go <- siw_xy_maxt_grid(DAT, CFG, PD, replicates = 200L, engine = "original"); expect_identical(g$table$p_outcome_maxT, go$table$p_outcome_maxT); expect_equal(g$table$observed_abs_correlation, go$table$observed_abs_correlation); expect_true(all(g$table$p_outcome_maxT >= 1 / 201 - 1e-12 & g$table$p_outcome_maxT <= 1)); expect_true(all(abs(g$table$p_outcome_maxT * 201 - round(g$table$p_outcome_maxT * 201)) < 1e-9))
})

test_that("MAXT failure accounting and degenerate samples: constant and all-missing columns, an all-degenerate family, outcome with missing values (original route), observed NA flagged", {
  xm <- cbind(k = rep(2, 8), z = rep(NA_real_, 8)); y <- c(1, 3, 2, 5, 4, 8, 6, 7); r <- siw_maxt_outcome(xm, y, 50L, 1L, colnames(xm), "o"); expect_equal(r$replicates_requested, 50L); expect_equal(r$replicates_successful, 0L); expect_true(all(r$max_stats == -Inf)); expect_true(all(is.na(r$table$observed_abs_correlation)))
  expect_equal(r$table$p_outcome_maxT, c(1 / 1, 1 / 1) * (1 + 0) / (1 + 0))                                                                                      # original rule with no finite maximum: (1 + 0) / (1 + 0)
  xm2 <- cbind(a = c(1, 2, 3, 4, 5, 6, 7, 8), k = rep(1, 8)); r2 <- siw_maxt_outcome(xm2, y, 30L, 2L, colnames(xm2), "o"); expect_equal(r2$replicates_successful, 30L); expect_true(is.na(r2$table$observed_abs_correlation[2])); expect_equal(r2$table$p_outcome_maxT[2], 1 / 31)         # an NA observed statistic gets the smallest attainable p in the original method (flagged below)
  yn <- y; yn[3] <- NA; r3 <- siw_maxt_outcome(xm2, yn, 20L, 2L, colnames(xm2), "o"); expect_match(r3$engine, "original"); l3 <- siw_maxt_legacy(xm2, yn, 20L, 2L); expect_identical(r3$table$p_outcome_maxT, l3$p)
  dg <- data.frame(outcome = "o", seed = 1, replicates_requested = 50L, replicates_successful = 50L, replicates_failed = 0L, near_tie_recomputed = 0L, p_changed_by_recompute = 0L, engine = "x", minimum_attainable_p = 1 / 51, stringsAsFactors = FALSE)
  d2 <- DAT[, 1:2, drop = FALSE]; d2$o <- as.numeric(DAT$UCLA_Lonliness_SCORE); d2$assessment_day <- DAT$assessment_day; d2$f1 <- DAT$UTCI_AVG_7D; d2$f2 <- rep(NA_real_, nrow(DAT)); tb <- data.frame(outcome = "o", exposure_field = c("f1", "f2"), observed_abs_correlation = c(0.2, NA), p_outcome_maxT = c(0.9, 1 / 51), stringsAsFactors = FALSE)
  a <- siw_maxt_assumptions(d2, CFG, list(table = tb, diagnostics = dg)); expect_true(all(a$status == "REVIEW")); expect_true(any(grepl("observed .r. not finite", a$item) & a$value == "1")); expect_true(any(grepl("fewer than all participants", a$item) & a$value == "1")); expect_true(any(grepl("eta squared", a$item))); expect_true(any(grepl("Monte Carlo", a$item)))
  expect_true("assessment_day" %in% names(DAT)); expect_equal(a$value[grepl("eta squared", a$item)], as.character(signif({ g <- factor(DAT$assessment_day); y0 <- as.numeric(DAT$UCLA_Lonliness_SCORE); sum(tapply(y0, g, function(z) length(z) * (mean(z) - mean(y0))^2)) / sum((y0 - mean(y0))^2) }, 4)))
})

# ---- synthetic frozen-format reference: exercises the runner, the strict rules and the failure paths (circular by construction; the non-circular check is validation/legacy_equivalence_daily_layer_synthetic.R)
syn_daily <- function(base, B = 300L) {
  unlink(base, recursive = TRUE); dir.create(base, recursive = TRUE); csv <- file.path(base, "syn.csv"); utils::write.csv(raw0, csv, row.names = FALSE, na = ""); refdir <- file.path(base, "ref"); dir.create(refdir)
  mx <- siw_xy_maxt_grid(DAT, CFG, PD, replicates = B)
  W <- function(x, f) utils::write.csv(x, file.path(refdir, f), row.names = FALSE, na = ""); W(XD, "XY_daily_all_1416.csv"); W(DY, "single_day_adjusted_regression_grid.csv"); W(mx$table, "selected_xy_maxT.csv"); list(base = base, csv = csv, refdir = refdir, B = B)
}
syn_prot <- function(Sy, refdir, out_json, tamper = 0L) {
  p <- siw_daily_protocol(); files <- c(XYD = "XY_daily_all_1416.csv", DAY = "single_day_adjusted_regression_grid.csv", MAXT = "selected_xy_maxT.csv"); tabs <- list()
  for (i in seq_along(p$reference_files)) { f <- file.path(refdir, p$reference_files[[i]]$file); if (file.exists(f)) { p$reference_files[[i]]$sha256 <- siw_file_hash(f)$value; p$reference_files[[i]]$bytes <- file.info(f)$size; tabs[[p$reference_files[[i]]$component]] <- utils::read.csv(f, stringsAsFactors = FALSE, check.names = FALSE, na.strings = c("", "NA")); p$reference_files[[i]]$expected_records <- nrow(tabs[[p$reference_files[[i]]$component]]) } }
  for (i in seq_along(p$comparisons)) { cc <- p$comparisons[[i]]; d <- tabs[[cc$reference]]; if (!is.null(d)) { p$comparisons[[i]]$expected_records <- nrow(d); p$comparisons[[i]]$expected_compared_cells <- sum(vapply(unlist(cc$fields), function(f) sum(is.finite(suppressWarnings(as.numeric(d[[f]])))), 0L)) + (if (i == 1L) tamper else 0L) } }
  p$parameters$maxt_replicates <- Sy$B; p$parameters$lags_subset <- as.list(S_lags); p$parameters$independent_refit_every <- 8L; p$protocol_path <- NULL; p$protocol_hash <- NULL; jsonlite::write_json(p, out_json, auto_unbox = TRUE, pretty = TRUE, null = "null", digits = NA); out_json
}
run_syn <- function(Sy, refdir = Sy$refdir, pj = NULL) { if (is.null(pj)) pj <- syn_prot(Sy, refdir, tempfile(fileext = ".json")); suppressMessages(siw_run_daily_layer_validation(Sy$csv, refdir, file.path(Sy$base, paste0("run_", basename(tempfile()))), CFG, protocol_path = pj)) }
vref <- function(Sy, edit, nm) { d <- file.path(Sy$base, paste0("ref_", nm)); unlink(d, recursive = TRUE); dir.create(d); file.copy(list.files(Sy$refdir, full.names = TRUE), d); edit(d); d }
rw <- function(d, f, fun) { p <- file.path(d, f); x <- utils::read.csv(p, stringsAsFactors = FALSE, check.names = FALSE, na.strings = c("", "NA")); x <- fun(x); utils::write.csv(x, p, row.names = FALSE, na = "") }
Sy0 <- syn_daily(file.path(tempdir(), "syn_daily_exact")); R0 <- run_syn(Sy0)

test_that("a reference equal to the package output passes the reproduction and verification statuses; MAXT assumptions stay REVIEW; runtime and replicate accounting are recorded", {
  s <- R0$statuses; expect_true(all(s[c("EXECUTION_STATUS", "INPUT_PROVENANCE_STATUS", "XYD_REPRODUCTION_STATUS", "XYD_VERIFICATION_STATUS", "DAY_REPRODUCTION_STATUS", "DAY_VERIFICATION_STATUS", "MAXT_REPRODUCTION_STATUS", "MAXT_VERIFICATION_STATUS", "COVERAGE_STATUS", "SOURCE_INTEGRITY_STATUS")] == "PASS")); expect_identical(unname(s[["MAXT_ASSUMPTIONS_STATUS"]]), "REVIEW"); expect_identical(R0$status, "OK_WITH_ASSUMPTIONS_UNDER_REVIEW")
  cv <- R0$coverage; expect_true(all(cv$cells_as_declared)); expect_true(all(cv$n_exact == cv$n_compared)); expect_equal(cv$n_compared[3], 480L); expect_true(all(R0$cat$xyd$n_different == 0L)); expect_true(all(R0$cat$day$n_different == 0L)); expect_true(all(R0$engine_verification$status == "PASS")); expect_true(all(R0$maxt$diagnostics$replicates_failed == 0L))
  st <- readLines(file.path(R0$out_dir, "DAILYLAYER_STATUS.txt")); expect_true(any(grepl("^MAXT_ASSUMPTIONS_STATUS=REVIEW", st))); expect_true(any(grepl("^J02_GLM_EPSILON_ENTRY_POINTS=OPEN", st))); expect_true(any(grepl("^FINAL_NINE_L56_NUMERICAL_VALIDATION=ACCEPTED_UNDER_V2_1", st))); expect_true(any(grepl("^RUNTIME_SECONDS=", st))); expect_true(any(grepl("^MAXT_REPLICATES_REQUESTED=300,300,300; SUCCESSFUL=300,300,300", st)))
  expect_true(all(is.finite(unlist(R0$seconds)))); expect_true(file.exists(file.path(R0$out_dir, "dailylayer_rng.txt"))); expect_true(file.exists(file.path(R0$out_dir, "maxt_assumption_assessment.csv"))); expect_true(all(R0$assumptions$status == "REVIEW")); expect_match(readLines(file.path(R0$out_dir, "SOURCE_FINGERPRINT.txt"))[3], "FALSE$")
})

test_that("each component fails on its own: XYD, DAY and MAXT differences, the exact MAXT criterion, categorical and one-sided missing values", {
  d1 <- vref(Sy0, function(d) rw(d, "XY_daily_all_1416.csv", function(x) { x$kendall_p[5] <- x$kendall_p[5] * 1.001; x }), "x1"); R1 <- run_syn(Sy0, d1); expect_equal(unname(R1$statuses[["XYD_REPRODUCTION_STATUS"]]), "FAIL"); expect_equal(unname(R1$statuses[["DAY_REPRODUCTION_STATUS"]]), "PASS"); expect_equal(unname(R1$statuses[["MAXT_REPRODUCTION_STATUS"]]), "PASS"); expect_identical(R1$status, "VERIFICATION_FAILURE")
  d2 <- vref(Sy0, function(d) rw(d, "single_day_adjusted_regression_grid.csv", function(x) { i <- which(x$status == "COMPLETED")[9]; x$coefficient[i] <- x$coefficient[i] * 1.01; x }), "d1"); R2 <- run_syn(Sy0, d2); expect_equal(unname(R2$statuses[["DAY_REPRODUCTION_STATUS"]]), "FAIL"); expect_equal(unname(R2$statuses[["XYD_REPRODUCTION_STATUS"]]), "PASS")
  d3 <- vref(Sy0, function(d) rw(d, "selected_xy_maxT.csv", function(x) { x$p_outcome_maxT[7] <- x$p_outcome_maxT[7] + 1 / (Sy0$B + 1); x }), "m1"); R3 <- run_syn(Sy0, d3); expect_equal(unname(R3$statuses[["MAXT_REPRODUCTION_STATUS"]]), "FAIL"); expect_equal(R3$coverage$n_different[3], 1L)           # one permutation count differs: not excused
  d4 <- vref(Sy0, function(d) rw(d, "selected_xy_maxT.csv", function(x) { x$p_outcome_maxT[7] <- x$p_outcome_maxT[7] * (1 + 1e-9); x }), "m2"); R4 <- run_syn(Sy0, d4); expect_equal(unname(R4$statuses[["MAXT_REPRODUCTION_STATUS"]]), "FAIL")                                                                 # even a 1e-9 relative difference fails the exact criterion
  d5 <- vref(Sy0, function(d) rw(d, "XY_daily_all_1416.csv", function(x) { x$status[3] <- "NOT_ESTIMABLE"; x }), "x2"); R5 <- run_syn(Sy0, d5); expect_equal(unname(R5$statuses[["XYD_REPRODUCTION_STATUS"]]), "FAIL"); d6 <- vref(Sy0, function(d) rw(d, "single_day_adjusted_regression_grid.csv", function(x) { x$robust_hc3_se[which(!is.na(x$robust_hc3_se))[1]] <- NA; x }), "d2"); R6 <- run_syn(Sy0, d6); expect_equal(unname(R6$statuses[["DAY_REPRODUCTION_STATUS"]]), "FAIL")
})

test_that("missing, altered or incomplete reference evidence fails the provenance and nothing is compared or passed", {
  d <- vref(Sy0, function(d) unlink(file.path(d, "selected_xy_maxT.csv")), "missing"); R <- run_syn(Sy0, d); expect_equal(unname(R$statuses[["INPUT_PROVENANCE_STATUS"]]), "FAIL"); expect_equal(unname(R$statuses[["COVERAGE_STATUS"]]), "FAIL"); expect_true(all(R$statuses[c("XYD_REPRODUCTION_STATUS", "DAY_REPRODUCTION_STATUS", "MAXT_REPRODUCTION_STATUS", "MAXT_VERIFICATION_STATUS", "MAXT_ASSUMPTIONS_STATUS")] == "NOT_TESTED")); expect_false(file.exists(file.path(R$out_dir, "xyd_comparison_summary.csv")))
  d2 <- vref(Sy0, function(d) rw(d, "XY_daily_all_1416.csv", function(x) { x$n[1] <- x$n[1] + 1L; x }), "hash"); R2 <- run_syn(Sy0, d2, pj = syn_prot(Sy0, Sy0$refdir, tempfile(fileext = ".json"))); expect_equal(unname(R2$statuses[["INPUT_PROVENANCE_STATUS"]]), "FAIL"); expect_true(any(grepl("SHA-256", R2$provenance$item) & !R2$provenance$ok))
  d3 <- vref(Sy0, function(d) rw(d, "single_day_adjusted_regression_grid.csv", function(x) { x[2, c("outcome", "metric", "window_or_lag", "model_tier")] <- x[1, c("outcome", "metric", "window_or_lag", "model_tier")]; x }), "dup"); R3 <- run_syn(Sy0, d3); expect_equal(unname(R3$statuses[["INPUT_PROVENANCE_STATUS"]]), "FAIL"); expect_true(any(R3$provenance$item == "keys unique" & !R3$provenance$ok))
  d4 <- vref(Sy0, function(d) rw(d, "selected_xy_maxT.csv", function(x) x[-4, ]), "drop"); R4 <- run_syn(Sy0, d4); expect_equal(unname(R4$statuses[["INPUT_PROVENANCE_STATUS"]]), "FAIL"); expect_true(any(R4$provenance$item == "the declared grid is complete" & !R4$provenance$ok))
  d5 <- vref(Sy0, function(d) rw(d, "XY_daily_all_1416.csv", function(x) { x$kendall_tau <- NULL; x }), "col"); R5 <- run_syn(Sy0, d5); expect_equal(unname(R5$statuses[["INPUT_PROVENANCE_STATUS"]]), "FAIL"); R6 <- run_syn(Sy0, pj = syn_prot(Sy0, Sy0$refdir, tempfile(fileext = ".json"), tamper = 1L)); expect_equal(unname(R6$statuses[["COVERAGE_STATUS"]]), "FAIL")
  expect_error(siw_run_daily_layer_validation(Sy0$csv, Sy0$refdir, file.path(Sy0$refdir, "inside"), CFG), "OUTPUT_AND_REFERENCE_FOLDERS_OVERLAP")
})

test_that("the run touches only its own folder, performs no other RNG use, makes no Firth / study-file call, and the entry points exist", {
  if (siw_skip_source_only("test-25-daily-layer: the run touches only its own folder, performs no other RNG use, makes ")) return(invisible(NULL))
  before <- vapply(list.files(Sy0$refdir, full.names = TRUE), function(f) siw_file_hash(f)$value, ""); run_syn(Sy0); expect_identical(before, vapply(list.files(Sy0$refdir, full.names = TRUE), function(f) siw_file_hash(f)$value, ""))
  src <- readLines(file.path(ROOT, "R", "daily_layer.R")); code <- src[!grepl("^\\s*#", src)]; expect_false(any(grepl("unlink\\(|file\\.remove|[^_a-z]set\\.seed\\(|runif|rnorm|mvrnorm|siw_firth|run_firth|read_sav|haven::", code))); expect_equal(sum(grepl("sample\\(y\\)", code)), 2L)
  expect_true(file.exists(file.path(ROOT, "run_daily_layer_validation.ps1"))); expect_true(file.exists(file.path(ROOT, "scripts", "_run_daily_layer.ps1"))); expect_true(any(grepl("mode == \"dailylayer\"", readLines(file.path(ROOT, "run.R"))))); expect_true(file.exists(file.path(ROOT, "validation", "legacy_equivalence_daily_layer_synthetic.R")))
})
